// 地铁图实网验收：独立浏览器和临时行程；不读取或修改用户备份。
const { chromium } = require('playwright');
const fs = require('node:fs/promises');
const path = require('node:path');
const assert = require('node:assert/strict');
const { createHash } = require('node:crypto');
const out = path.join(__dirname,'amap-subway-live-20261116');
const key='xingjian-lvji-preview-v1';
const seed={version:1,tripId:'subway-live-check',started:true,entryMode:'new',section:'days',mapOpen:true,day:0,origin:'青岛',destination:'青岛',start:'2026-11-16',days:1,people:1,rooms:1,budget:1000,plans:[[]],customPlaces:{},savedPlaces:[],wishPlaces:[],dailyRoutes:{},dailyTiming:{},messages:[],undo:[]};
(async()=>{
  await fs.mkdir(out,{recursive:true});
  const browser=await chromium.launch({headless:true,executablePath:'C:/Users/LENOVO/AppData/Local/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-win64/chrome-headless-shell.exe',args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
  const context=await browser.newContext({viewport:{width:1600,height:1000}});
  await context.addInitScript(({key,value})=>localStorage.setItem(key,JSON.stringify(value)),{key,value:seed});
  await context.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin==='http://127.0.0.1:18647'&&(u.pathname.startsWith('/api/backup/')||u.pathname==='/api/providers/config'))return route.abort('blockedbyclient');return route.continue();});
  const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message.slice(0,200)));
  try{
    await page.goto('http://127.0.0.1:18647/next/');await page.locator('.map-actions').waitFor({timeout:35000});
    const before=await page.evaluate(key=>localStorage.getItem(key),key);
    await page.getByRole('button',{name:'地铁',exact:true}).click();
    const frame=page.frameLocator('iframe[title="地铁线路图"]');
    await frame.locator('svg[adcode="3702"]').waitFor({timeout:30000});
    await frame.getByText('青岛北站',{exact:true}).first().waitFor({state:'attached',timeout:15000});
    await frame.getByRole('button',{name:'放大地铁图'}).waitFor({state:'visible'});
    await page.waitForTimeout(2500);
    await page.screenshot({path:path.join(out,'青岛地铁.png')});
    await frame.getByText('青岛北站',{exact:true}).first().click();
    await page.waitForTimeout(800);
    await page.screenshot({path:path.join(out,'青岛地铁-站点点击.png')});
    await frame.getByText('设为起点',{exact:true}).click();
    await frame.getByText('台东',{exact:true}).first().click();
    await frame.getByText('设为终点',{exact:true}).click();
    await page.waitForTimeout(1500);
    await page.screenshot({path:path.join(out,'青岛地铁-站点路线.png')});
    const closeRoute=frame.locator('.route_close_btn');
    await closeRoute.waitFor({state:'visible'});
    const routeCloseBox=await closeRoute.boundingBox();
    const zoomBox=await frame.getByRole('button',{name:'放大地铁图'}).boundingBox();
    assert.ok(routeCloseBox.y >= zoomBox.y + zoomBox.height, '清除路线按钮不能覆盖地铁图缩放按钮');
    await closeRoute.click();await closeRoute.waitFor({state:'hidden'});
    await page.waitForTimeout(800);
    const stageBox=await frame.locator('.stage').boundingBox();
    const dragBefore=await frame.locator('.stage').screenshot();
    await page.mouse.move(stageBox.x+stageBox.width*.35,stageBox.y+stageBox.height*.25);await page.mouse.down();
    await page.mouse.move(stageBox.x+stageBox.width*.45,stageBox.y+stageBox.height*.3,{steps:10});await page.mouse.up();
    await page.waitForTimeout(800);
    const dragAfter=await frame.locator('.stage').screenshot();
    const hash=x=>createHash('sha256').update(x).digest('hex');
    assert.notEqual(hash(dragBefore),hash(dragAfter),'拖动后地铁线路图应变化');
    const zoomBefore=await frame.locator('.stage').screenshot({path:path.join(out,'青岛缩放前.png')});
    for(let i=0;i<4;i++) await frame.getByRole('button',{name:'缩小地铁图'}).click();
    await page.waitForTimeout(1500);
    const zoomAfter=await frame.locator('.stage').screenshot({path:path.join(out,'青岛缩放后.png')});
    assert.notEqual(hash(zoomBefore),hash(zoomAfter),'地铁图缩放按钮应改变实际图面');
    await frame.getByLabel('选择地铁城市').selectOption('3301');
    await frame.locator('svg[adcode="3301"]').waitFor({timeout:30000});
    assert.equal(await frame.locator('svg[adcode="3702"]').count(),0,'切换杭州后不得保留青岛线路');
    await frame.getByText('凤起路',{exact:true}).first().waitFor({state:'attached',timeout:15000});
    await page.waitForTimeout(2500);await page.screenshot({path:path.join(out,'杭州地铁.png')});
    await page.setViewportSize({width:1100,height:800});await page.waitForTimeout(800);
    const bounds=await page.locator('.subway-overlay').boundingBox();
    const mapBounds=await page.locator('.travel-map').boundingBox();
    assert.ok(bounds.x>=mapBounds.x-1&&bounds.x+bounds.width<=mapBounds.x+mapBounds.width+1,'地铁图不能溢出工作台地图区域');
    await page.screenshot({path:path.join(out,'杭州地铁-窄窗口.png')});
    await page.getByRole('button',{name:'关闭地铁图'}).click();
    assert.equal(await page.locator('iframe[title="地铁线路图"]').count(),0);
    assert.equal(await page.locator('.map-actions').isVisible(),true,'关闭地铁图后应回到工作台地图');
    assert.equal(await page.evaluate(key=>localStorage.getItem(key),key),before,'浏览地铁图不得写入旅行数据');
    assert.deepEqual(errors,[]);
    console.log('PASS 真实地铁图：默认青岛、站点选择及线路高亮、关闭线路、拖动和缩放、切换杭州、关闭返回地图；临时行程未变。');
  }finally{await context.close();await browser.close();}
})().catch(e=>{console.error('FAILED:',e.message);process.exitCode=1});
